"""库存价值计算。以下函数签名是唯一权威定义，不要修改本文件。"""


def total_value(prices, quantities):
    """返回逐项价格乘以数量后的总金额。

    prices 与 quantities 等长；不含任何折扣逻辑。
    """
    return sum(price * quantity for price, quantity in zip(prices, quantities))


def format_cny(amount):
    """把金额格式化为人民币字符串，保留两位小数。"""
    return "CNY {:.2f}".format(amount)
